cat > ParseBinlog.cs << 'CEOF'
using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Print all errors
Console.WriteLine("=== ALL ERRORS ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    var project = "";
    var node = e.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    Console.WriteLine($"[{project}] {e.Code}: {e.Text}");
    if (!string.IsNullOrEmpty(e.File))
        Console.WriteLine($"  File: {e.File}({e.LineNumber},{e.ColumnNumber})");
    Console.WriteLine();
}

// Print all warnings
Console.WriteLine("=== ALL WARNINGS ===");
var warnings = build.FindChildrenRecursive<Warning>();
foreach (var w in warnings)
{
    var project = "";
    var node = w.Parent;
    while (node != null)
    {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    Console.WriteLine($"[{project}] {w.Code}: {w.Text}");
}

// Print project dependency info
Console.WriteLine("\n=== PROJECT BUILD RESULTS ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    var hasErrors = p.FindChildrenRecursive<Error>().Any();
    Console.WriteLine($"  {p.Name} - Succeeded: {p.Succeeded}, HasErrors: {hasErrors}");
}
