using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Get all errors with full context
Console.WriteLine("=== ERRORS WITH CONTEXT ===");
var errors = build.FindChildrenRecursive<Error>();
foreach (var e in errors)
{
    var project = "";
    var target = "";
    var node = e.Parent;
    while (node != null)
    {
        if (node is Target t && string.IsNullOrEmpty(target)) target = t.Name;
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    Console.WriteLine($"Project: {project}");
    Console.WriteLine($"Target: {target}");
    Console.WriteLine($"Code: {e.Code}");
    Console.WriteLine($"Message: {e.Text}");
    Console.WriteLine($"File: {e.File}({e.LineNumber},{e.ColumnNumber})");
    Console.WriteLine();
}

// Check project references
Console.WriteLine("=== PROJECT REFERENCES (from Items) ===");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects.Take(10))
{
    var refs = p.FindChildrenRecursive<Item>()
        .Where(i => i.Name == "ProjectReference")
        .Select(i => i.Text)
        .Distinct();
    if (refs.Any())
        Console.WriteLine($"{p.Name} references: {string.Join(", ", refs)}");
}
